/**
 * vCard generation for DÉ's contact information.
 * Standard VCF 3.0 format — works on iPhone, Android, and desktop.
 */

// Contact photo, base64-encoded PNG (300x300)
const CONTACT_PHOTO = "";

export function generateVCard(): string {
  const noteText = [
    "Executive Voice AI Assistant Lauren",
    "Streamlined System",
    "+",
    "Revenue Growth Strategies",
    "=",
    "5X Your Business & You on Vacation",
    "",
    "",
    "How?",
    "\u2022 Executive AI - (Leads/Retention)",
    "\u2022 Automation - (Speed)",
    "\u2022 Revenue Growth Visual Dashboards",
  ].join("\\n");

  return [
    "BEGIN:VCARD",
    "VERSION:3.0",
    "N:;D\u00C9;;;",
    "FN:D\u00C9",
    "ORG:Luxury Dream Lounge",
    "TITLE:Founder & CEO | Business Consultant & Architect",
    "EMAIL;TYPE=WORK:Elevate@LuxuryDreamLounge.com",
    "TEL;TYPE=WORK,VOICE:+15022768098",
    "item1.TEL:+15022768098",
    "item1.X-ABLabel:Office Assistant",
    "TEL;TYPE=CELL,VOICE:+15022086240",
    "ADR;TYPE=WORK:;;6844 Bardstown Rd #538;Louisville;KY;40291;United States",
    "URL:https://www.LuxuryDreamLounge.com",
    `PHOTO;ENCODING=b;TYPE=PNG:${CONTACT_PHOTO}`,
    `NOTE:${noteText}`,
    "END:VCARD",
  ].join("\r\n");
}

export function downloadVCard(): void {
  const vcf = generateVCard();
  const blob = new Blob([vcf], { type: "text/vcard;charset=utf-8" });
  const url = URL.createObjectURL(blob);

  const a = document.createElement("a");
  a.href = url;
  a.download = "DE-LuxuryDreamLounge.vcf";
  a.style.display = "none";
  document.body.appendChild(a);
  a.click();

  // Cleanup
  setTimeout(() => {
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }, 100);
}
